<?php
namespace App\Queries\Catalog;
use App\Models\{Banner,FeaturedCollection,FeaturedProduct,Lookbook,Product,Promotion};
class HomepageQuery { public function data(): array { $now=now(); $active=fn($q)=>$q->where('is_active',true)->where(fn($q)=>$q->whereNull('starts_at')->orWhere('starts_at','<=',$now))->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>=',$now)); $data=['banners'=>Banner::query()->tap($active)->orderBy('sort_order')->get(),'featuredCollections'=>FeaturedCollection::query()->tap($active)->with('collection:id,name,slug,hero_image')->orderBy('sort_order')->get(),'featuredProducts'=>FeaturedProduct::query()->tap($active)->with('product.brand:id,name,slug','product.images:id,product_id,url,is_primary')->orderBy('sort_order')->get(),'lookbooks'=>Lookbook::query()->where('status','published')->where('published_at','<=',$now)->with(['items.product:id,name,slug'])->latest('published_at')->take(6)->get(),'newProducts'=>Product::query()->where('status','active')->where('is_active',true)->where('is_new',true)->with(['brand:id,name,slug','images'=>fn($q)=>$q->where('is_primary',true)->select('id','product_id','url')])->select('id','name','slug','price','brand_id')->latest()->take(8)->get()]; if(Promotion::query()->where('is_active',true)->where(fn($q)=>$q->whereNull('starts_at')->orWhere('starts_at','<=',$now))->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>=',$now))->exists()) { $data['promotionalProducts']=Product::query()->where('status','active')->where('is_active',true)->whereHas('promotions',fn($q)=>$q->where('is_active',true)->where(fn($q)=>$q->whereNull('starts_at')->orWhere('starts_at','<=',$now))->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>=',$now)))->with(['brand:id,name,slug','images'=>fn($q)=>$q->where('is_primary',true)->select('id','product_id','url')])->select('id','name','slug','price','brand_id')->latest()->take(8)->get(); } return $data; } }
